def make_x(rng,n):
 X=rng.random((n,20));X[:,0]=-4.2+7.2*X[:,0];X[:,1:10]=(X[:,1:10]>.5);X[:,10:]*=10
 return X
meta=[];factors=[];offsets=[]
for i in range(20):
 low=-4.2 if i==0 else 0
 scale=7.2 if i==0 else (1 if i<10 else 10)
 ks=[None] if 0<i<10 else [None]+([-2.,0.,2.] if i==0 else [2.5,5.,7.5])
 for k in ks:
  if k is None:
   mean=low+scale*.5;sd=scale*(.5 if 0<i<10 else np.sqrt(1/12));a=1/sd;d=-mean/sd
  else:
   t=(k-low)/scale;mean=(1-t)**2/2;sd=np.sqrt((1-t)**3/3-mean**2);a=1/(scale*sd);d=-mean/sd
  meta.append((i,k));factors.append(a);offsets.append(d)
names=[(-1,-1)]+[(j,-1) for j in range(len(meta))]
for a in range(len(meta)):
 for b in range(a+1,len(meta)):
  if meta[a][0]!=meta[b][0]:names.append((a,b))
def design(X):
 n=X.shape[0];B=np.empty((n,len(meta)))
 for j,(i,k) in enumerate(meta):B[:,j]=(X[:,i] if k is None else np.maximum(X[:,i]-k,0))*factors[j]+offsets[j]
 A=np.empty((n,len(names)));A[:,0]=1;A[:,1:54]=B
 for j in range(54,len(names)):
  a,b=names[j];A[:,j]=B[:,a]*B[:,b]
 return A
rng=np.random.default_rng(448);m=len(names);G=np.zeros((m,m));v=np.zeros(m)
for chunk in range(20):
 X=make_x(rng,10000);y=predict(X).reshape(-1);A=design(X);G+=A.T@A;v+=A.T@y
G/=200000;v/=200000
G0=G[:54,:54];B=G[54:,:54]
R=G[54:,54:]-B@np.linalg.solve(G0,B.T)
vy=v[54:]-B@np.linalg.solve(G0,v[:54])
sel=[];scores=[]
Xt=make_x(np.random.default_rng(449),30000);yt=predict(Xt).reshape(-1);T=design(Xt)
for it in range(250):
 diag=np.diag(R).copy();diag=np.maximum(diag,1e-10);score=vy**2/diag
 if len(sel)>0:score[sel]=-1
 best=int(np.argmax(score));sel.append(best);scores.append(score[best])
 u=R[:,best].copy();vy-=u*vy[best]/diag[best];R-=np.outer(u,u)/diag[best]
 if it+1 in [10,20,30,40,60,80,100,120,160,200,250]:
  idx=np.array(list(range(54))+[s+54 for s in sel]);coef=np.linalg.solve(G[np.ix_(idx,idx)]+np.eye(len(idx))*1e-8,v[idx]);yh=T[:,idx]@coef;e=yt-yh
  print('interactions',len(sel),'RMSE',np.sqrt(np.mean(e*e)),'R2',1-np.var(e)/np.var(yt),'PMAE',np.mean(np.abs(1/(1+np.exp(-yt))-1/(1+np.exp(-yh)))))
print('selected')
for step,s in enumerate(sel[:160]):
 a,b=names[s+54];print(step+1,meta[a],meta[b],round(scores[step],7))
print('SEL',sel)

